def is_wet_race(year: int, gp: str, *, db_path: str, session_type: str = "R",
                threshold: float = 0.1) -> bool:
    """True if this session's wetness exceeds threshold (#575 wet flag).

    session_surface_features.wet_lap_fraction is populated for R sessions
    only (the population script is R-only), so it is NULL for every S/Q/SQ
    session today. When the flag is NULL, fall back to a physics-local
    compound-based proxy: the fraction of this session's laps on
    INTERMEDIATE/WET compound. This is what actually catches a wet sprint
    (e.g. Belgium/Austria S 2023, 403/480 laps on inters) that the naive
    R-only flag would silently wave through as dry.
    """
    try:
        con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    except sqlite3.Error:
        return False
    try:
        row = con.execute(
            "SELECT f.wet_lap_fraction FROM session_surface_features f "
            "JOIN sessions s ON s.id=f.session_id "
            "WHERE s.year=? AND s.session_type=? AND s.gp_name=? LIMIT 1",
            (year, session_type, gp),
        ).fetchone()
    except sqlite3.Error:
        row = None
    if row is not None and row[0] is not None:
        con.close()
        return bool(row[0] > threshold)
    try:
        counts = con.execute(
            "SELECT "
            "SUM(CASE WHEN l.compound IN ('INTERMEDIATE','WET') THEN 1 ELSE 0 END), "
            "COUNT(*) "
            "FROM lap_times l JOIN sessions s ON s.id=l.session_id "
            "WHERE s.year=? AND s.session_type=? AND s.gp_name=?",
            (year, session_type, gp),
        ).fetchone()
    except sqlite3.Error:
        counts = None

